import{_ as e,c as r,o as i,af as n}from"./chunks/framework.BKeRpnBD.js";const b=JSON.parse('{"title":"30、【離】 離下離上","description":"溫公易說 - 30、【離】 離下離上","frontmatter":{"title":"30、【離】 離下離上","description":"溫公易說 - 30、【離】 離下離上"},"headers":[],"relativePath":"classics/wengong/031.md","filePath":"classics/wengong/031.md"}'),l={name:"classics/wengong/031.md"};function t(h,a,s,o,d,c){return i(),r("div",null,[...a[0]||(a[0]=[n('<h1 id="_30、【離】-離下離上" tabindex="-1">30、【離】 離下離上 <a class="header-anchor" href="#_30、【離】-離下離上" aria-label="Permalink to “30、【離】 離下離上”">​</a></h1><h3 id="彖曰-離-麗也。日月麗乎天-百穀草木麗乎土。重明以麗乎正-乃化成天下。柔麗乎中正-故亨。是以畜牝牛吉也。" tabindex="-1">彖曰：離，麗也。日月麗乎天，百穀草木麗乎土。重明以麗乎正，乃化成天下。柔麗乎中正，故亨。是以畜牝牛吉也。 <a class="header-anchor" href="#彖曰-離-麗也。日月麗乎天-百穀草木麗乎土。重明以麗乎正-乃化成天下。柔麗乎中正-故亨。是以畜牝牛吉也。" aria-label="Permalink to “彖曰：離，麗也。日月麗乎天，百穀草木麗乎土。重明以麗乎正，乃化成天下。柔麗乎中正，故亨。是以畜牝牛吉也。”">​</a></h3><p>離利貞亨，離麗也。麗者，不可以不正也。夫明者，常失於察，察之甚者，或入於邪。是以聖人重明以麗乎正，乃能化成天下。柔者，失於弱而不立，故柔麗乎中正，然後乃亨。夫太明則察，太昧則蔽。二以明德而用中正，是以獲元吉也。</p><h3 id="象曰-明兩作離-大人以繼明照於四方。" tabindex="-1">象曰：明兩作離，大人以繼明照於四方。 <a class="header-anchor" href="#象曰-明兩作離-大人以繼明照於四方。" aria-label="Permalink to “象曰：明兩作離，大人以繼明照於四方。”">​</a></h3><h3 id="初九-履錯然-敬之-無咎-象曰-履錯之敬-以闢咎也。" tabindex="-1">初九：履錯然，敬之，無咎 象曰：履錯之敬，以闢咎也。 <a class="header-anchor" href="#初九-履錯然-敬之-無咎-象曰-履錯之敬-以闢咎也。" aria-label="Permalink to “初九：履錯然，敬之，無咎 象曰：履錯之敬，以闢咎也。”">​</a></h3><p>初九敬之無咎何？夫火者，始於焰，焰而至於不可撲滅者也。是以明者慮於未兆，見於未萌，方事之初而錯然矜慎，以避其咎也。</p><h3 id="六二-黃離-元吉-象曰-黃離元吉-得中道也。" tabindex="-1">六二：黃離，元吉 象曰：黃離元吉，得中道也。 <a class="header-anchor" href="#六二-黃離-元吉-象曰-黃離元吉-得中道也。" aria-label="Permalink to “六二：黃離，元吉 象曰：黃離元吉，得中道也。”">​</a></h3><h3 id="九三-日昃之離-不鼓缶而歌-則大耋之嗟-兇-象曰-日昃之離-何可久也" tabindex="-1">九三：日昃之離，不鼓缶而歌，則大耋之嗟，兇 象曰：日昃之離，何可久也？ <a class="header-anchor" href="#九三-日昃之離-不鼓缶而歌-則大耋之嗟-兇-象曰-日昃之離-何可久也" aria-label="Permalink to “九三：日昃之離，不鼓缶而歌，則大耋之嗟，兇 象曰：日昃之離，何可久也？”">​</a></h3><h3 id="九四-突如其來如-焚如-死如-棄如-象曰-突如其來如-無所容也。" tabindex="-1">九四：突如其來如，焚如，死如，棄如 象曰：突如其來如，無所容也。 <a class="header-anchor" href="#九四-突如其來如-焚如-死如-棄如-象曰-突如其來如-無所容也。" aria-label="Permalink to “九四：突如其來如，焚如，死如，棄如 象曰：突如其來如，無所容也。”">​</a></h3><p>突者，子之不順者也。火性炎上，而九四以剛乘剛，用其不正以陵於上。若火之方熾，其來甚盛，極盛必衰，故死如棄如也。死者，禍之極也。棄者，眾所不與也。</p><h3 id="六五-出涕沱若-戚嗟若-吉-象曰-六五之吉-離王公也。" tabindex="-1">六五：出涕沱若，戚嗟若，吉 象曰：六五之吉，離王公也。 <a class="header-anchor" href="#六五-出涕沱若-戚嗟若-吉-象曰-六五之吉-離王公也。" aria-label="Permalink to “六五：出涕沱若，戚嗟若，吉 象曰：六五之吉，離王公也。”">​</a></h3><h3 id="上九-王用出徵-有嘉折首-獲匪其醜-無咎-象曰-王用出徵-以正邦也。" tabindex="-1">上九：王用出徵，有嘉折首，獲匪其醜，無咎 象曰：王用出徵，以正邦也。 <a class="header-anchor" href="#上九-王用出徵-有嘉折首-獲匪其醜-無咎-象曰-王用出徵-以正邦也。" aria-label="Permalink to “上九：王用出徵，有嘉折首，獲匪其醜，無咎 象曰：王用出徵，以正邦也。”">​</a></h3>',12)])])}const f=e(l,[["render",t]]);export{b as __pageData,f as default};
